.consent-checkbox {
    display: flex;
    align-items: center;
    margin-bottom: 20px;
    text-align: left;
}

.consent-checkbox input[type="checkbox"] {
    margin-right: 10px;
}

.consent-checkbox label {
    margin-bottom: 0;
    display: inline; /* Para que el texto se alinee bien con el checkbox */
}

.consent-checkbox a {
    color: #007bff;
    text-decoration: none;
}

.consent-checkbox a:hover {
    text-decoration: underline;
}

button {
    background-color: #28a745;
    color: white;
    padding: 10px 15px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 16px;
    width: 100%;
}

button:hover {
    background-color: #218838;
}

.flashes {
    list-style: none;
    padding: 0;
    margin-bottom: 20px;
    text-align: left;
}

.flashes li {
    padding: 10px;
    border-radius: 4px;
    margin-bottom: 10px;
}

.flashes .error {
    background-color: #ffdddd;
    color: #d8000c;
    border: 1px solid #d8000c;
}

.flashes .success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.flashes .info {
    background-color: #d1ecf1;
    color: #0c5460;
